from datetime import datetime
from pydantic import ConfigDict, Field
from src.models.sensor_batch_input import SensorBatchInput


class BrickBatch(SensorBatchInput):
    batch_id: str = Field(
        ...,
        description="Unique batch identifier, e.g. 'BLOCA-2026-000123'.",
    )

    timestamp: datetime = Field(
        ...,
        description=(
            "End of cooling phase for this batch. Generated on the Raspberry Pi "
            "(FastAPI) at the moment the batch completes, and sent as part of the "
            "upload payload -- not auto-generated by Django on receipt, since the "
            "RPi may queue the batch locally and retry later if it loses internet."
        ),
    )

    image_url: str = Field(
        ...,
        description=(
            "Cloud storage URL of the ESP32-CAM image captured at end of cooling "
            "phase, uploaded via Django to S3/GCS. Required for every batch, "
            "regardless of quality_class outcome, since the CNN needs labeled "
            "examples of all three classes (Acceptable, Defective, Reject)."
        ),
    )

    compressive_strength_mpa: float | None = Field(
        default=None,
        ge=0.0,
        le=15.0,
        description="Ground-truth compressive strength from the lab crush test, in MPa. Null until the lab result is in.",
    )

    quality_class: int | None = Field(
        default=None,
        ge=0,
        le=2,
        description="Ground-truth QA label: 0 = Acceptable, 1 = Defective, 2 = Reject. Null until Mark (QA) labels the image.",
    )

    model_config = ConfigDict(
        json_schema_extra={
            "examples": [
                {
                    "batch_id": "BLOCA-2026-000123",
                    "timestamp": "2026-07-23T09:14:00+08:00",
                    "compaction_temp_c": 152.4,
                    "hydraulic_pressure_mpa": 0.19,
                    "heating_duration_min": 18.5,
                    "cooling_duration_min": 12.0,
                    "compressed_height_mm": 55.2,
                    "heater_current_a": 4.1,
                    "image_url": "https://bloca-storage.s3.amazonaws.com/batches/BLOCA-2026-000123.jpg",
                    "compressive_strength_mpa": 6.3,
                    "quality_class": 0,
                }
            ]
        }
    )
